WFJ.Data.add("spell", {
  [409073] = { "I tuoi attacchi in mischia generano $N1 rabbia.", nil, 0x92c24d5d, nil, "um" },
  [409163] = { "Incidi sulla tua cintura la runa Rabbia Concentrata:\n\n$I1\nRiduce di $N1 il costo in rabbia delle tue abilità offensive.", nil, 0xbd819656, nil, "um" },
  [409239] = { "Scaglia istantaneamente entrambe le armi contro tutti i bersagli entro $N1 m, infliggendo il $N2% dei danni dell'arma.", nil, 0x989dea54, nil, "um" },
  [409240] = { "Scaglia istantaneamente entrambe le armi contro tutti i bersagli entro $N1 m, infliggendo il $N2% dei danni dell'arma con i pugnali e il $N3% con tutte le altre armi.", nil, 0x9f297d5b, nil, "um" },
  [409324] = { "Per i prossimi $D1, il $N2% dei tuoi danni viene convertito in cure su un massimo di $N3 membri del gruppo vicini, e il $N4% delle tue cure viene convertito in danni sul bersaglio più recente della tua ⟦Flame Shock=Folgore del Fuoco⟧.", "Danni convertiti in cure sui membri del gruppo vicini, e cure convertite in danni sul bersaglio di ⟦Flame Shock=Folgore del Fuoco⟧.", 0xa920f4c5, 0xabc76e9a, "uu" },
  [409333] = { "Per i prossimi $D1, il $N2% dei tuoi danni viene convertito in cure su un massimo di $N3 membri del gruppo vicini, e il $N4% delle tue cure viene convertito in danni sul bersaglio più recente della tua ⟦Flame Shock=Folgore del Fuoco⟧.", nil, 0xef189613, nil, "um" },
  [409337] = { "Per i prossimi $D1, il $N2% dei tuoi danni viene convertito in cure su un massimo di $N3 membri del gruppo vicini, e il $N4% delle tue cure viene convertito in danni sul bersaglio più recente della tua ⟦Flame Shock=Folgore del Fuoco⟧.", nil, 0xef189613, nil, "um" },
  [409365] = { nil, "Velocità d'attacco.", nil, 0x62b8a592, "mu" },
  [409368] = { "I danni e la salute del tuo famiglio aumentano del $N1% e la sua rigenerazione di Focus del $N2%. Inoltre, il Ringhio del tuo famiglio ora provoca anche il bersaglio, inducendolo ad attaccarlo per $D1.", nil, 0x0e6fe86a, nil, "um" },
  [409372] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", "Provocato.", 0x71de38fd, 0x36f56123, "uu" },
  [409379] = { "Dai l'ordine di uccidere, aumentando del $N1% i danni inflitti dal tuo famiglio con Sfregio e Morso per $D1. Ogni Sfregio o Morso del famiglio riduce il bonus ai danni del $N3%.", nil, 0x912d6e1b, nil, "um" },
  [409396] = { "Dai l'ordine di uccidere, aumentando del $N1% i danni inflitti dal tuo famiglio con Sfregio e Morso per $D1. Ogni Sfregio o Morso del famiglio riduce il bonus ai danni del $N3%.", "Danni inflitti da Sfregio e Morso aumentati del $N1%.", 0x912d6e1b, 0xce508390, "uu" },
  [409418] = { "Dai l'ordine di uccidere, aumentando del $N1% i danni inflitti dal tuo famiglio con Sfregio e Morso per $D1. Ogni Sfregio o Morso del famiglio riduce il bonus ai danni del $N3%.", "Aumenta del $N1% i danni inflitti con Sfregio e Morso.", 0x22bcaf5c, 0x952b882c, "uu" },
  [409428] = { "Aumenta del $N1% la tua probabilità di colpo critico e riduce del $N2% il costo in mana di tutte le tue abilità di tiro.", nil, 0x2cf87e48, nil, "um" },
  [409433] = { "Infliggi il $N1% dei danni dell'arma, rinnovando il Morso attivo sul tuo bersaglio e attivando un effetto:\n\nMorso del Serpente - Infligge istantaneamente il $N2% dei danni inflitti dal tuo Morso del Serpente.\n\nMorso della Vipera - Ti rigenera istantaneamente mana pari al $N3% della quantità totale prosciugata dal tuo Morso della Vipera.\n\n⟦Scorpid Sting=Morso dello Scorpide⟧ - Tenta di disarmare il bersaglio per $D1. Questo effetto non può verificarsi più di una volta ogni $N5 min.", nil, 0x1ccad7e0, nil, "um" },
  [409493] = { "Infliggi il $N1% dei danni dell'arma, rinnovando il Morso attivo sul tuo bersaglio e attivando un effetto:\n\nMorso del Serpente - Infligge istantaneamente il $N2% dei danni inflitti dal tuo Morso del Serpente.\n\nMorso della Vipera - Ti rigenera istantaneamente mana pari al $N3% della quantità totale prosciugata dal tuo Morso della Vipera.\n\n⟦Scorpid Sting=Morso dello Scorpide⟧ - Tenta di disarmare il bersaglio per $D1. Questo effetto non può verificarsi più di una volta ogni $N5 min.", nil, 0x1ccad7e0, nil, "um" },
  [409494] = { "Infliggi il $N1% dei danni dell'arma, rinnovando il Morso attivo sul tuo bersaglio e attivando un effetto:\n\nMorso del Serpente - Infligge istantaneamente il $N2% dei danni inflitti dal tuo Morso del Serpente.\n\nMorso della Vipera - Ti rigenera istantaneamente mana pari al $N3% della quantità totale prosciugata dal tuo Morso della Vipera.\n\n⟦Scorpid Sting=Morso dello Scorpide⟧ - Tenta di disarmare il bersaglio per $D1. Questo effetto non può verificarsi più di una volta ogni $N5 min.", nil, 0x1ccad7e0, nil, "um" },
  [409495] = { "Infliggi il $N1% dei danni dell'arma, rinnovando il Morso attivo sul tuo bersaglio e attivando un effetto:\n\nMorso del Serpente - Infligge istantaneamente il $N2% dei danni inflitti dal tuo Morso del Serpente.\n\nMorso della Vipera - Ti rigenera istantaneamente mana pari al $N3% della quantità totale prosciugata dal tuo Morso della Vipera.\n\n⟦Scorpid Sting=Morso dello Scorpide⟧ - Tenta di disarmare il bersaglio per $D1. Questo effetto non può verificarsi più di una volta ogni $N5 min.", "Disarmato.", 0x1ccad7e0, 0x98985eda, "uu" },
  [409504] = { "I tuoi critici in mischia e a distanza aumentano la tua potenza d'attacco del $N1% della tua Agilità attuale per $D1.", nil, 0xe5905d7e, nil, "um" },
  [409507] = { "I tuoi critici a distanza aumentano la tua potenza d'attacco del $N1% della tua Agilità per $D1.", "Potenza d'attacco aumentata di $N1.", 0xe1757db0, 0x44b5cb33, "uu" },
  [409580] = { "Il Cacciatore invoca il cuore di un leone, aumentando del $N1% gli attributi totali e di $N2 la potenza d'attacco di tutti gli alleati vicini, e aumentando di un ulteriore $N3% gli attributi totali del Cacciatore.", "Aumenta del $N1% gli attributi del Cacciatore.", 0xda4d40c0, 0x077a68f0, "uu" },
  [409583] = { "Il Cacciatore invoca il cuore di un leone, aumentando del $N1% gli attributi totali di tutti gli alleati vicini, e aumentando di un ulteriore $N2% gli attributi totali del Cacciatore.", "Aumenta gli attributi del $N1% e la potenza d'attacco di $N2.", 0x35b31cc8, 0xb8d3cc6d, "uu" },
  [409593] = { "Tenti di finire un bersaglio ferito con un attacco a distanza che infligge il $N1% dei danni dell'arma più $N2. Tiro Mortale non ha una portata minima. Il tempo di recupero di Tiro Mortale si azzera se viene usato su un nemico con il $N3% di salute o meno.", nil, 0xeae59b96, nil, "um" },
  [409687] = { "Aumenta del $N1% i danni inflitti dall'arma nella mano secondaria e fa sì che il tuo Assalto del Raptor colpisca con entrambe le armi quando combatti con due armi.", nil, 0x096cde57, nil, "um" },
  [409691] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409693] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409748] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409750] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409751] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409752] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409754] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409755] = { "Un attacco potente che aumenta di $N1 i danni in mischia.", nil, 0xac0dc93d, nil, "um" },
  [409805] = { "Ottieni l'abilità Assalti Selvaggi:\n\n$I1\nMentre sei in Forma Felina, Forma d'Orso o Dire Bear Form, i membri del gruppo o dell'incursione entro $N1 m ottengono una maggiore ferocia in combattimento. Ogni colpo in mischia ha una probabilità del $N2% di conferire all'attaccante un attacco aggiuntivo con il $N3% di potenza d'attacco in più. Nessun effetto se il bersaglio beneficia già di Totem della Furia del Vento.", nil, 0x788aa8b1, nil, "um" },
  [409809] = { "Ottieni l'abilità Istinto di Sopravvivenza:\n\n$I1\nQuando viene attivato, ti conferisce il $N1% della tua salute massima e aumenta del $N2% tutte le cure non fisiche che effettui per $D1. Quando l'effetto termina, la salute viene persa. Utilizzabile in tutte le forme tranne Forma di Lunagufo.\n\nInoltre, rigeneri $N4 rabbia ogni volta che schivi mentre sei in Forma d'Orso o Dire Bear Form, $N5 energia mentre sei in Forma Felina, o il $N6% del tuo mana massimo mentre sei in qualsiasi altra forma.", nil, 0x073a0328, nil, "um" },
  [409810] = { "Ottieni l'abilità Crescita Rigogliosa:\n\n$I1\nCura il bersaglio e il suo gruppo di $N1 in $D1. I membri del gruppo devono trovarsi entro $N3 m dal bersaglio. La cura è rapida all'inizio e rallenta man mano che Crescita Rigogliosa si avvicina alla fine della sua durata.", nil, 0x1229731d, nil, "um" },
  [409813] = { "Ottieni l'abilità Eclissi:\n\n$I1\nIl tuo incantesimo Ira Silvana riduce di $D1 il tempo di lancio dei tuoi prossimi $N1 incantesimi Fuoco Stellare. Conserva fino a $N3 cariche. Dura $D2.", nil, 0x2e5d5870, nil, "um" },
  [409819] = { { "Ottieni l'abilità Ruggito Selvaggio:\n\n$I1\n|CFFFFFFFFRichiede Forma Felina|R\nMossa risolutiva che aumenta del $N1% i danni fisici inflitti mentre sei in Forma Felina. Dura di più per ogni punto combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", "Ottieni l'abilità Ruggito Selvaggio:\n\n$I1\n|CFFFF2020Richiede Forma Felina|R\nMossa risolutiva che aumenta del $N1% i danni fisici inflitti mentre sei in Forma Felina. Dura di più per ogni punto combo:\n $N2 punto: $N3 s\n $N4 punti: $N5 s\n $N6 punti: $N7 s\n $N8 punti: $N9 s\n $N10 punti: $N11 s", shape = { "11/0", "11/0" }, key = { "85d8aafe43173e40", "b9f99412b4b8e235" } }, nil, 0xb2ad9246, nil, "um" },
  [409824] = { "Riduce di $D1 il tempo di recupero globale delle tue abilità Rinvigorimento e Bocciolo di Vita e ottieni l'abilità Bocciolo di Vita:\n\n$I1\nCura il bersaglio di $N2 in $D2. Quando Bocciolo di Vita completa la sua durata o viene dissolto, il bersaglio viene curato istantaneamente di $N4 e il Druido recupera metà del costo dell'incantesimo. Questo effetto può accumularsi fino a $N5 volte sullo stesso bersaglio.", nil, 0x2e4374dc, nil, "um" },
  [409826] = { "Ottieni l'abilità Furia della Natura:\n\n$I1\nAumenta le tue cure di una quantità pari al $N1% dei tuoi danni magici da natura per $D1.", nil, 0x7b50d5d3, nil, "um" },
  [409830] = { "Ottieni l'abilità Nutrizione:\n\n$I1\nCura un bersaglio amico di $N1. Cura un ulteriore $N2% se sul bersaglio è attivo un tuo effetto di Rinvigorimento, Ricrescita, Bocciolo di Vita o Crescita Rigogliosa. Questo incantesimo beneficia di tutti gli effetti associati a Tocco Curativo o Ricrescita e li attiva.", nil, 0x2ef6e8eb, nil, "um" },
  [409831] = { "Ottieni l'abilità Stato Onirico:\n\n$I1\nI critici non periodici dei tuoi incantesimi offensivi ti conferiscono il $N1% della tua rigenerazione del mana durante il lancio per $D1.", nil, 0xc097fe72, nil, "um" },
  [409832] = { "Ottieni l'abilità Fury of Stormrage:\n\n$I1\nRiduce del $N1% il costo in mana di Ira Silvana e, ogni volta che infliggi danni con Ira Silvana, hai una probabilità del $N2% che il tuo prossimo lancio di Tocco Curativo entro $D1 sia istantaneo e lanciabile in qualsiasi forma. Permette di lanciare Ira Silvana in forma di Albero della Vita.", nil, 0x58a6d63b, nil, "um" },
  [409856] = { "Inizia un rituale per liberare lo spirito di un avventuriero caduto.", nil, 0x1348cc33, nil, "um" },
  [409918] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [409922] = { "Ottieni l'abilità Martello del Virtuoso:\n\n$I1\nColpisce con il martello il bersaglio attuale e fino a $N1 bersagli aggiuntivi vicini, infliggendo a ciascuno danni da sacro pari a $N2 volte i danni al secondo della tua arma nella mano primaria. Tempo di recupero condiviso con Assalto del Crociato.", nil, 0x41bcfc78, nil, "um" },
  [409924] = { "Ottieni l'abilità Tempesta Divina:\n\n$I1\nUn attacco istantaneo con l'arma che infligge il $N1% dei danni dell'arma a un massimo di $N2 nemici entro $N3 m. Tempesta Divina cura fino a $N4 membri del gruppo o dell'incursione per un totale pari al $N5% dei danni inflitti.", nil, 0x1d2c1934, nil, "um" },
  [409925] = { "Ottieni l'abilità Luce Divina:\n\n$I1\nCura un bersaglio amico di $N1. Il $N2% di qualsiasi cura in eccesso sul bersaglio viene convertito in uno scudo assorbente che dura $D1. Più lanci di Luce Divina non accumulano questo scudo.\n\nLuce Divina beneficia di tutti i talenti e gli effetti che si attivano da Luce Sacra o la modificano.", nil, 0xbbe5ffdd, nil, "um" },
  [409930] = { nil, "Pieno d'ispirazione.", nil, 0x12978998, "mu" },
  [409934] = { "Ottieni l'abilità Ira Vendicatrice:\n\n$I1\nAumenta del $N1% tutti i danni inflitti e le cure effettuate per $D1. Causa Rigorosità e non può essere usata mentre Rigorosità è attiva.", nil, 0x21255755, nil, "um" },
  [409935] = { "Ottieni l'abilità Imposizione del Sacrificio:\n\n$I1\nFa sì che il membro del gruppo o dell'incursione bersaglio trasferisca all'incantatore il $N1% dei danni subiti. Dura $D1 o finché l'incantatore non ha trasferito il $N3% della sua salute massima.", nil, 0x043ae106, nil, "um" },
  [409936] = { "Ottieni l'abilità Inspiration Exemplar:\n\n$I1\nLa tua presenza ispiratrice dissolve periodicamente gli effetti di paura e di sonno sui membri del gruppo vicini.", nil, 0x338ec99b, nil, "um" },
  [409938] = { "Ottieni l'abilità ⟦Fire Nova=Esplosione di Fuoco⟧, che sostituisce il tuo ⟦Fire Nova Totem=Totem dell'Esplosione di Fuoco⟧:\n\n$I1\nIl tuo incantesimo ⟦Fire Nova Totem=Totem dell'Esplosione di Fuoco⟧ viene sostituito da ⟦Fire Nova=Esplosione di Fuoco⟧, che fa emettere danni al tuo totem del fuoco attuale nella sua posizione.", nil, 0xac6b1f14, nil, "um" },
  [409940] = { "Ottieni l'abilità Specializzazione: ⟦Dual Wield=Combattimento con Due Armi⟧:\n\n$I1\nAumenta del $N1% la tua probabilità d'impatto con incantesimi e attacchi in mischia quando combatti con due armi, la tua abilità Assalto della Tempesta ora colpisce con entrambe le armi quando combatti con due armi, e aumenta del $N2% i danni inflitti dall'arma nella mano secondaria.", nil, 0x93277d64, nil, "um" },
  [409941] = { "Ottieni l'abilità Scudo d'Acqua:\n\n$I1\nL'incantatore è circondato da $N1 globi d'acqua. Quando un incantesimo, un attacco in mischia o a distanza colpisce l'incantatore, o quando uno degli incantesimi dell'incantatore ottiene un effetto critico, all'incantatore viene rigenerato il $N2% del mana massimo, consumando un globo d'acqua. Si può attivare un solo globo ogni pochi secondi. Dura $D1.\n\nSullo Sciamano può essere attivo un solo Scudo Elementale alla volta.", nil, 0x5c50298d, nil, "um" },
  [409943] = { "Ottieni l'abilità Maestria nello Scudo:\n\n$I1\nOgni volta che blocchi, rigeneri mana pari al $N1% del tuo mana massimo e ottieni Armatura pari al $N2% del valore di armatura del tuo scudo, effetto che si accumula fino a $N3 volte. Inoltre ottieni sempre il $N4% di probabilità di blocco in più e il $N5% di valore di blocco in più.\n\nInoltre, ogni volta che usi un'abilità Folgore, ottieni $N6 danni magici per ogni punto di abilità in Difesa oltre $N7. Dura $D1.", nil, 0xd7939443, nil, "um" },
  [409944] = { "Ottieni l'abilità Guida Ancestrale:\n\n$I1\nPer i prossimi $D1, il $N2% dei tuoi danni viene convertito in cure su un massimo di $N3 membri del gruppo vicini, e il $N4% delle tue cure viene convertito in danni sul bersaglio più recente della tua Folgore del Fuoco.", nil, 0x0da0019e, nil, "um" },
  [409945] = { "Ottieni l'abilità Sovraccarico:\n\n$I1\nConferisce ai tuoi incantesimi Dardo Fulminante e Catena di Fulmini una probabilità del $N1% di lanciare sullo stesso bersaglio, senza costi aggiuntivi, un secondo incantesimo simile che infligge metà dei danni e non genera minaccia.", nil, 0x7b4659a8, nil, "um" },
  [409946] = { "Ottieni l'abilità Arma del Maelstrom:\n\n$I1\nQuando infliggi danni con un attacco in mischia, hai il $N1% di probabilità (in base alla velocità dell'arma) di ridurre del $N2% il tempo di lancio e il costo in mana del tuo prossimo ⟦Lightning Bolt=Dardo Fulminante⟧. Si accumula fino a $N3 volte. Dura $D1.", nil, 0xf6dd7ebb, nil, "um" },
  [409947] = { "Ottieni l'abilità ⟦Earth Shield=Scudo di Terra⟧:\n\n$I1\nProtegge il bersaglio con uno scudo di terra, riducendo del $N1% il tempo di lancio o di incanalamento perso quando subisce danni, e fa sì che gli attacchi curino il bersaglio protetto di $N2. Questo effetto può verificarsi solo una volta ogni pochi secondi. $N3 cariche. Dura $D1. ⟦Earth Shield=Scudo di Terra⟧ può essere posizionato su un solo bersaglio alla volta.", nil, 0x745da8e2, nil, "um" },
  [409951] = { "Ottieni l'abilità Spirit of the Alpha:\n\n$I1\nInfonde nel bersaglio lo spirito di un lupo alfa, aumentando del $N1% tutta la minaccia generata dal bersaglio per $D1. Limite: $N3 bersaglio. Se lanciato su un bersaglio diverso da te, lo Sciamano ottiene anche Loyal Beta, che aumenta del $N4% i danni fisici inflitti e riduce del $N5% tutta la minaccia generata per $D2. Un bersaglio non può avere contemporaneamente Spirit of the Alpha e Loyal Beta.", nil, 0x95679687, nil, "um" },
  [409952] = { "Ottieni l'abilità ⟦Lava Burst=Getto di Lava⟧:\n\n$I1\nScagli lava fusa contro il bersaglio, infliggendo $N1 danni da fuoco. Se la tua Folgore del Fuoco è sul bersaglio, ⟦Lava Burst=Getto di Lava⟧ infligge il $N2% di danni in più.", nil, 0x93940084, nil, "um" },
  [409953] = { "Ottieni l'abilità Sferzata Lavica:\n\n$I1\nCarichi di lava l'arma nella mano secondaria, infliggendo istantaneamente il $N1% dei danni dell'arma nella mano secondaria. I danni aumentano del $N2% se l'arma nella mano secondaria è incantata con Arma della Lingua di Fuoco.", nil, 0xb4d0dacb, nil, "um" },
  [409954] = { "Ottieni l'abilità Marea Benefica:\n\n$I1\nCura un bersaglio amico di $N1 in $D1 e aumenta del $N3% l'efficacia dei tuoi lanci di Catena di Guarigione diretti su quel bersaglio.", nil, 0x16fbb037, nil, "um" },
  [409955] = { "Ottieni l'abilità Way of Earth:\n\n$I1\nMentre Arma della Roccia Dura è attiva sulla tua arma nella mano primaria e hai uno scudo equipaggiato, generi il $N1% di minaccia in più, ottieni il $N2% di salute in più, subisci il $N3% di danni in meno, la tua probabilità di subire colpi critici dagli attacchi in mischia è ridotta del $N4%, e Folgore della Terra provoca i bersagli inducendoli ad attaccarti e ha un tempo di recupero separato dagli altri incantesimi Folgore, ma la sua portata è ridotta alla distanza da mischia. Tuttavia, la portata dei tuoi incantesimi Dardo Fulminante, Catena di Fulmini, Catena di Guarigione, Ondata di Cura e Getto di Lava è ridotta di $N5 m.", nil, 0x4f96cd74, nil, "um" },
  [409957] = { "Ottieni l'abilità Tiro Stabilizzato:\n\n$I1\nUn tiro stabilizzato che infligge il $N1% dei danni dell'arma a distanza.", nil, 0x2697bd4f, nil, "um" },
  [409958] = { "Ottieni l'abilità Precisione da Cecchino:\n\n$I1\nAumenta del $N1% la tua probabilità di colpo critico e riduce del $N2% il costo in mana di tutte le tue abilità di tiro.", nil, 0xdadd56b2, nil, "um" },
  [409959] = { "Ottieni l'abilità ⟦Expose Weakness=Debolezza Esposta⟧:\n\n$I1\nI tuoi critici in mischia e a distanza aumentano la tua potenza d'attacco del $N1% della tua Agilità attuale per $D1.", nil, 0x3b41ea35, nil, "um" },
  [409960] = { "Ottieni l'abilità Cobra Slayer:\n\n$I1\nMorso della Mangusta ora ha una probabilità del $N1% di attivarsi a ogni tuo attacco in mischia, e del $N2% quando un nemico schiva. Questa probabilità si accumula, aumentando del $N3% a ogni attacco successivo se non si azzera. Morso della Mangusta infligge anche danni aggiuntivi pari al $N4% della tua potenza d'attacco.", nil, 0x9c1a661a, nil, "um" },
  [409961] = { "Ottieni l'abilità Specializzazione: ⟦Dual Wield=Combattimento con Due Armi⟧:\n\n$I1\nAumenta del $N1% i danni inflitti dall'arma nella mano secondaria e fa sì che il tuo Assalto del Raptor colpisca con entrambe le armi quando combatti con due armi.", nil, 0x7bbfdf06, nil, "um" },
  [409962] = { "Ottieni l'abilità Affinità Animale:\n\n$I1\nI danni e la salute del tuo famiglio aumentano del $N1% e la sua rigenerazione di Focus del $N2%. Inoltre, il Ringhio del tuo famiglio ora provoca anche il bersaglio, inducendolo ad attaccarlo per $D1.", nil, 0x9b4757cc, nil, "um" },
  [409974] = { "Ottieni l'abilità Tiro Mortale:\n\n$I1\nTenti di finire un bersaglio ferito con un attacco a distanza che infligge il $N1% dei danni dell'arma più $N2. Tiro Mortale non ha una portata minima. Il tempo di recupero di Tiro Mortale si azzera se viene usato su un nemico con il $N3% di salute o meno.", nil, 0xf8c116e8, nil, "um" },
  [409976] = { "Ottieni l'abilità Tiro della Chimera:\n\n$I1\nInfliggi il $N1% dei danni dell'arma, rinnovando il Morso attivo sul tuo bersaglio e attivando un effetto:\n\nMorso del Serpente - Infligge istantaneamente il $N2% dei danni inflitti dal tuo Morso del Serpente.\n\nMorso della Vipera - Ti rigenera istantaneamente mana pari al $N3% della quantità totale prosciugata dal tuo Morso della Vipera.\n\nMorso dello Scorpide - Tenta di disarmare il bersaglio per $D1. Questo effetto non può verificarsi più di una volta ogni $N5 min.", nil, 0x5f9d939b, nil, "um" },
  [409979] = { "Ottieni l'abilità Lupo Solitario:\n\n$I1\nInfliggi il $N1% di danni in più con tutti gli attacchi mentre non hai un famiglio attivo.", nil, 0x14ffc98e, nil, "um" },
})
